L["General"] = "Geral"
L["On WoW Forever: hits are read live from the game and matched to your casts and swings."] = "No WoW Forever: os golpes são lidos ao vivo do jogo e comparados com seus feitiços e golpes de arma."
L["On WoW Forever: each fight is summarised from Blizzard's damage meter once it ends."] = "No WoW Forever: cada combate é resumido a partir do medidor de dano da Blizzard quando acaba."
L["Every feed reads the combat log as it happens."] = "Cada painel lê o registro de combate em tempo real."
L["Blizzard"] = "Blizzard"
L["Hide Blizzard's damage numbers"] = "Esconder os números de dano da Blizzard"
L["Turns off the numbers Blizzard floats over the target, so only these feeds show your damage."] = "Desliga os números que a Blizzard faz flutuar sobre o alvo, para que só estes painéis mostrem seu dano."
L["Post-fight summary"] = "Resumo pós-combate"
L["Keep on screen"] = "Manter na tela"
L["How long a target's summary stays reachable once you first look at it. The window runs per target."] = "Por quanto tempo o resumo de um alvo continua disponível depois que você o vê pela primeira vez. A janela é contada por alvo."
L["Fade out over"] = "Sumir ao longo de"
